# Focus: Hybrid Search and Reranking
keyword_rank = {"doc-a": 1, "doc-b": 2}
semantic_rank = {"doc-b": 1, "doc-c": 2}
rrf = {doc: sum(1/(60+rank) for ranking in [keyword_rank, semantic_rank] if (rank := ranking.get(doc)) is not None) for doc in set(keyword_rank)|set(semantic_rank)}
print(sorted(((round(score,5), doc) for doc,score in rrf.items()), reverse=True))
